-- Part 6 (diversification pass): online MCQ bank (comp_mcq_questions) for coating_supervisor
-- ("سرپرست پوشش/کاتدیک"). This role had ZERO rows in comp_mcq_questions before this seed
-- (verified via `select job_role, count(*) from comp_mcq_questions group by 1` during the
-- audit). ~38 questions, APPROVED and active, spanning TECHNICAL/GENERAL/HSE/SCENARIO/JUDGMENT/
-- PROBLEM_SOLVING/CASE_STUDY and difficulty 1-3, with varied stem formats (fact-recall, "کدام
-- گزینه نادرست است", scenario best-action, numeric/calculation) to avoid a single predictable
-- phrasing pattern. Domain grounding: SSPC-SP/NACE surface-prep standards, dry film thickness
-- (DFT) measurement (SSPC-PA2), holiday/spark testing (NACE RP0188/AWWA), cathodic protection
-- basics (NACE SP0169, rectifier/anode fundamentals), confined-space and blasting/spraying HSE.
-- Same shape/rotation technique as supabase/seed/mcq_questions_seed.sql (correct_option is
-- rotated 0..3 across rows so the answer position isn't fixed). Idempotent via
-- (job_role, md5(stem_fa)) unique index.

insert into comp_mcq_questions (job_role, category, topic, difficulty, stem_fa, options, correct_option, explanation_fa, standard_ref, approval_status, active)
select 'coating_supervisor', x ->> 0, x ->> 1, (x ->> 2)::smallint, x ->> 3,
  (select jsonb_agg(x -> 4 -> ((i - r.k + 4) % 4) order by i) from generate_series(0, 3) i),
  ((n - 1) % 4)::smallint, x ->> 6, x ->> 7, 'APPROVED', true
